// INTERVAL FRAMEWORK UTILITIES

// Standard sort: by start time ascending, then by end time ascending for ties
function sortIntervals(intervals) {
    return intervals.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
}

// Overlap check: do intervals a and b overlap?
function overlaps(a, b) {
    // a=[a0,a1], b=[b0,b1]
    // Overlap iff NOT (a ends before b starts OR b ends before a starts)
    return !(a[1] < b[0] || b[1] < a[0]);
    // Equivalent: a[0] <= b[1] && b[0] <= a[1]
}

// After sorting, only need to check if current interval overlaps with PREVIOUS merged end
// This is the key simplification that makes O(n) post-sort scan possible

// THREE CANONICAL PATTERNS:

// PATTERN 1: MERGE OVERLAPPING INTERVALS
// Scan sorted intervals. Extend current merge window or start new.
function mergePattern(intervals) {
    sortIntervals(intervals);
    const result = [intervals[0]];
    for (let i = 1; i < intervals.length; i++) {
        const prev = result[result.length - 1];
        const curr = intervals[i];
        if (curr[0] <= prev[1]) {          // overlap: extend
            prev[1] = Math.max(prev[1], curr[1]);
        } else {
            result.push([...curr]);         // no overlap: new interval
        }
    }
    return result;
}

// PATTERN 2: COUNT CONFLICTS / REMOVE TO ELIMINATE CONFLICTS
// Sort, then track end of last non-conflicting interval
function conflictPattern(intervals) {
    sortIntervals(intervals);
    let conflicts = 0, lastEnd = -Infinity;
    for (const [start, end] of intervals) {
        if (start < lastEnd) conflicts++;         // conflict with previous
        else lastEnd = end;                        // no conflict: update lastEnd
    }
    return conflicts;
}

// PATTERN 3: MINIMUM RESOURCES (rooms needed)
// Track active intervals with a min-heap of end times
function resourcePattern(intervals) {
    sortIntervals(intervals);
    const heap = []; // min-heap of end times (active interval ends)
    for (const [start, end] of intervals) {
        // Free rooms whose meeting ended before this starts
        // heap.sort() for interview clarity; use proper MinHeap in production
        heap.sort((a,b) => a-b);
        if (heap.length > 0 && heap[0] <= start) heap.shift();
        heap.push(end);
    }
    return heap.length; // max simultaneous = rooms needed
}

console.log(mergePattern([[1,3],[2,6],[8,10],[15,18]]));  // [[1,6],[8,10],[15,18]]
console.log(conflictPattern([[1,2],[2,3],[3,4],[1,3]]));  // 1 (remove [1,3])
console.log(resourcePattern([[0,30],[5,10],[15,20]]));    // 2

