// MERGE INTERVALS (#56) — O(n log n) time, O(n) space
function merge(intervals) {
    if (intervals.length <= 1) return intervals;
    intervals.sort((a,b) => a[0] - b[0]); // sort by start time

    const result = [intervals[0].slice()]; // copy first interval

    for (let i = 1; i < intervals.length; i++) {
        const [start, end] = intervals[i];
        const prev = result[result.length - 1];

        if (start <= prev[1]) {
            // OVERLAP or CONTAINMENT: extend end if needed
            prev[1] = Math.max(prev[1], end);
        } else {
            // NO OVERLAP: start new interval
            result.push([start, end]);
        }
    }
    return result;
}

console.log(merge([[1,3],[2,6],[8,10],[15,18]])); // [[1,6],[8,10],[15,18]]
console.log(merge([[1,4],[4,5]]));                // [[1,5]] (touching = overlap)
console.log(merge([[1,4],[2,3]]));                // [[1,4]] (containment)

// INSERT INTERVAL (#57) — insert into sorted non-overlapping list O(n)
function insert(intervals, newInterval) {
    const result = [];
    let i = 0;
    const [ns, ne] = newInterval;

    // Phase 1: add all intervals ending BEFORE new interval starts
    while (i < intervals.length && intervals[i][1] < ns) {
        result.push(intervals[i++]);
    }

    // Phase 2: merge all overlapping intervals with newInterval
    let [mergedS, mergedE] = [ns, ne];
    while (i < intervals.length && intervals[i][0] <= mergedE) {
        mergedS = Math.min(mergedS, intervals[i][0]);
        mergedE = Math.max(mergedE, intervals[i][1]);
        i++;
    }
    result.push([mergedS, mergedE]);

    // Phase 3: add remaining intervals
    while (i < intervals.length) result.push(intervals[i++]);

    return result;
}

