// NON-OVERLAPPING INTERVALS (#435)
// Minimum removals = n - max_kept
// O(n log n) time, O(1) space
function eraseOverlapIntervals(intervals) {
    if (!intervals.length) return 0;
    // Sort by END time (not start!): greedy keeps earliest-ending intervals
    intervals.sort((a,b) => a[1] - b[1]);

    let kept = 1;                        // keep the first interval (earliest end)
    let lastEnd = intervals[0][1];       // end time of last kept interval

    for (let i = 1; i < intervals.length; i++) {
        const [start, end] = intervals[i];
        if (start >= lastEnd) {          // NO CONFLICT: can keep this one
            kept++;
            lastEnd = end;               // update last kept end
        }
        // CONFLICT: skip this interval (remove it)
        // Greedy: since sorted by end, the kept interval has a smaller end
        // which is ALWAYS better for future intervals
    }
    return intervals.length - kept;      // minimum removals
}

console.log(eraseOverlapIntervals([[1,2],[2,3],[3,4],[1,3]])); // 1 (remove [1,3])
console.log(eraseOverlapIntervals([[1,2],[1,2],[1,2]]));       // 2
console.log(eraseOverlapIntervals([[1,2],[2,3]]));             // 0 (touching, not overlapping)

// WHY SORT BY END (not start) — proof by example:
// intervals: [[1,10],[2,3],[3,4]]
// Sort by START: [[1,10],[2,3],[3,4]]
//   Keep [1,10] (first), conflict [2,3] (remove), conflict [3,4] (remove) -> kept=1, remove=2
//   But optimal is: remove [1,10], keep [2,3] and [3,4] -> remove=1
// Sort by END: [[2,3],[3,4],[1,10]]
//   Keep [2,3], keep [3,4] (start=3 >= end=3), conflict [1,10] (remove) -> kept=2, remove=1 ✓

// MINIMUM NUMBER OF ARROWS TO BURST BALLOONS (#452)
// Similar greedy: sort by end, shoot arrow when overlap ends
function findMinArrowShots(points) {
    points.sort((a,b) => a[1] - b[1]);
    let arrows = 1, arrowPos = points[0][1];
    for (let i = 1; i < points.length; i++) {
        if (points[i][0] > arrowPos) { // balloon starts after current arrow
            arrows++;
            arrowPos = points[i][1]; // new arrow at this balloon's end
        }
    }
    return arrows;
}

