// MEETING ROOMS I (#252) — can one person attend all?
// O(n log n) time, O(1) space
function canAttendMeetings(intervals) {
    intervals.sort((a,b) => a[0] - b[0]); // sort by start
    for (let i = 1; i < intervals.length; i++) {
        if (intervals[i][0] < intervals[i-1][1]) return false; // conflict
    }
    return true;
}

console.log(canAttendMeetings([[0,30],[5,10],[15,20]])); // false (0-30 conflicts with 5-10)
console.log(canAttendMeetings([[7,10],[2,4]]));           // true (sorted: [2,4],[7,10] no conflict)

// MEETING ROOMS II (#253) — minimum rooms needed
// O(n log n) time, O(n) space
function minMeetingRooms(intervals) {
    if (!intervals.length) return 0;
    intervals.sort((a,b) => a[0] - b[0]); // sort by start

    // Min-heap of end times for ongoing meetings
    const heap = []; // sorted ascending in interview (proper heap in production)

    for (const [start, end] of intervals) {
        // Reuse the room whose meeting ends earliest if it finishes before this starts
        if (heap.length > 0) heap.sort((a,b) => a-b); // maintain min-heap order
        if (heap.length > 0 && heap[0] <= start) {
            heap.shift(); // reuse this room: remove its old end time
        }
        heap.push(end); // add this meeting to some room
    }
    return heap.length; // rooms in use = max simultaneous
}

console.log(minMeetingRooms([[0,30],[5,10],[15,20]])); // 2
console.log(minMeetingRooms([[7,10],[2,4]]));           // 1

// TRACE for [[0,30],[5,10],[15,20]] sorted by start:
// [0,30]: heap empty. Push 30. heap=[30]. rooms=1.
// [5,10]: heap=[30]. 30>5 (no free room). Push 10. heap=[10,30]. rooms=2.
// [15,20]: heap=[10,30]. 10<=15 (room free!). Remove 10, push 20. heap=[20,30]. rooms=2.
// Final heap size=2. Answer=2.

// ALTERNATIVE: TWO SORTED ARRAYS (start times and end times separately)
function minMeetingRoomsAlt(intervals) {
    const starts = intervals.map(i => i[0]).sort((a,b)=>a-b);
    const ends   = intervals.map(i => i[1]).sort((a,b)=>a-b);
    let rooms = 0, endPtr = 0;
    for (const start of starts) {
        if (start < ends[endPtr]) rooms++;  // new room needed
        else endPtr++;                        // reuse: advance end pointer
    }
    return rooms;
}

