// JUMP GAME I (#55) — can you reach the end?
// O(n) time, O(1) space
function canJump(nums) {
    let maxReach = 0;
    for (let i = 0; i < nums.length; i++) {
        if (i > maxReach) return false; // stuck: can't reach position i
        maxReach = Math.max(maxReach, i + nums[i]);
        if (maxReach >= nums.length - 1) return true;
    }
    return true; // survived entire array
}

console.log(canJump([2,3,1,1,4])); // true
console.log(canJump([3,2,1,0,4])); // false (stuck at index 3: nums[3]=0)

// JUMP GAME II (#45) — minimum jumps to reach end
// O(n) time, O(1) space
function jump(nums) {
    let jumps = 0;
    let curEnd = 0;    // end of current jump's reachable window
    let farthest = 0;  // farthest reachable from any position in current window

    for (let i = 0; i < nums.length - 1; i++) {
        // Update farthest reachable from position i
        farthest = Math.max(farthest, i + nums[i]);

        if (i === curEnd) {
            // Reached boundary of current jump: must make another jump
            jumps++;
            curEnd = farthest; // next jump extends to farthest reachable
            if (curEnd >= nums.length - 1) break; // reached end
        }
    }
    return jumps;
}

console.log(jump([2,3,1,1,4])); // 2 (jump from 0->1->4 or 0->4)
console.log(jump([2,3,0,1,4])); // 2
console.log(jump([1]));          // 0 (already at end)

