// GAS STATION (#134) — greedy start point
function canCompleteCircuit(gas, cost) {
    let total = 0, curr = 0, start = 0;
    for (let i = 0; i < gas.length; i++) {
        const net = gas[i] - cost[i]; // net gain at station i
        total += net;
        curr  += net;
        if (curr < 0) { // can't continue from current start
            start = i + 1; // try starting from next station
            curr = 0;
        }
    }
    return total >= 0 ? start : -1; // total>=0 means a solution exists
}

